#!/usr/bin/env python3
"""Compile all canonical console inputs and reject any stale generated byte."""
import subprocess
import sys
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUTPUTS=('workbench.js','document-graph.js','workbench.css','sdd-console.css')


def main():
    static=ROOT/'architect_framework/console/static'
    before={name:(static/name).read_bytes() for name in OUTPUTS}
    commands=([[str(ROOT/'node_modules/.bin/tsc'),'-p',str(ROOT/'architect_framework/console/tsconfig.json')]] if (ROOT/'node_modules/.bin/tsc').exists() else []) + [
        [sys.executable,str(ROOT/'scripts/build_console_graph.py')],
        [sys.executable,str(ROOT/'scripts/build_console_styles.py')]]
    for command in commands:
        result=subprocess.run(command,cwd=ROOT)
        if result.returncode:return result.returncode
    stale=[name for name,data in before.items() if (static/name).read_bytes()!=data]
    for name in stale:print('STALE generated console asset: '+name,file=sys.stderr)
    return 1 if stale else 0


if __name__=='__main__':raise SystemExit(main())
